func assertRoundTrip(t *testing.T, name string, encoded term.Term, decode func(term.Term) (term.Term, bool)) {
	t.Helper()
	canonical, valid := decode(encoded)
	if !valid {
		t.Fatalf("%s rejected encoded value", name)
	}
	if !term.Equal(encoded, canonical) {
		t.Fatalf("%s canonical form = %v, want %v", name, canonical, encoded)
	}
}

